// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.frontier.oracle;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.math.BigInteger;
import java.util.LinkedHashMap;
import java.util.Map;

import org.junit.jupiter.api.Test;

class FrontierOracleSemanticsTest {

	private static final OracleFrontierLayout X = OracleFrontierLayout.of("x");
	private static final OracleFrontierLayout XY = OracleFrontierLayout.of("x", "y");

	@Test
	void projectionCoalescesBagMultiplicityAndPreservesRows() {
		OracleBag bag = OracleBag.empty()
				.plus(binding("x", 1L, "y", 10L), 2)
				.plus(binding("x", 1L, "y", 11L), 7)
				.plus(binding("y", 12L), 3);

		OracleBag projected = bag.project(X);

		assertEquals(BigInteger.valueOf(12L), projected.cardinality());
		assertEquals(BigInteger.valueOf(9L), projected.multiplicity(binding("x", 1L)));
		assertEquals(BigInteger.valueOf(3L), projected.multiplicity(OracleBinding.empty()));
		assertEquals(2, projected.distinctCardinality());
	}

	@Test
	void frontierSeparatesEveryBoundMaskAndRetainsOrderedTupleIdentity() {
		OracleBag bag = OracleBag.empty()
				.plus(binding("x", 1L, "y", 2L), 3)
				.plus(binding("x", 1L), 4)
				.plus(binding("y", 2L), 5)
				.plus(OracleBinding.empty(), 6);

		OracleFrontierMeasure frontier = OracleFrontierMeasure.fromBag(bag, XY);

		assertEquals(4, frontier.byMask().size());
		assertEquals(ExactRational.of(18), frontier.mass());
		assertEquals(ExactRational.of(7), frontier.project(X).weights().get(binding("x", 1L)));
		assertEquals(ExactRational.of(11), frontier.project(X).weights().get(OracleBinding.empty()));
		assertNotEquals(XY, OracleFrontierLayout.of("y", "x"));
	}

	@Test
	void naturalJoinMultipliesCompatibleBagMultiplicity() {
		OracleBag left = OracleBag.empty()
				.plus(binding("s", 1L, "x", 10L), 2)
				.plus(binding("s", 2L, "x", 20L), 3);
		OracleBag right = OracleBag.empty()
				.plus(binding("s", 1L, "y", 30L), 5)
				.plus(binding("s", 1L, "y", 31L), 7)
				.plus(binding("s", 3L, "y", 32L), 11);

		OracleBag joined = left.naturalJoin(right);

		assertEquals(BigInteger.valueOf(24L), joined.cardinality());
		assertEquals(BigInteger.TEN, joined.multiplicity(binding("s", 1L, "x", 10L, "y", 30L)));
		assertEquals(BigInteger.valueOf(14L),
				joined.multiplicity(binding("s", 1L, "x", 10L, "y", 31L)));
	}

	@Test
	void unionAndFilterAreBagLinear() {
		OracleBag left = OracleBag.empty().plus(binding("x", 1L), 2).plus(binding("x", 2L), 3);
		OracleBag right = OracleBag.empty().plus(binding("x", 1L), 5);

		OracleBag union = left.union(right);

		assertEquals(BigInteger.valueOf(7L), union.multiplicity(binding("x", 1L)));
		assertEquals(BigInteger.valueOf(3L), union.filter(mu -> mu.termId("x").orElseThrow() == 2L).cardinality());
	}

	@Test
	void existsAndNotExistsRetainOuterMultiplicityOnce() {
		OracleBag left = OracleBag.empty().plus(binding("x", 1L), 7).plus(binding("x", 2L), 3);
		OracleBag right = OracleBag.empty().plus(binding("x", 1L, "y", 9L), 11);

		assertEquals(OracleBag.empty().plus(binding("x", 1L), 7), left.exists(right));
		assertEquals(OracleBag.empty().plus(binding("x", 2L), 3), left.notExists(right));
		assertEquals(left, left.exists(right).union(left.notExists(right)));
	}

	@Test
	void minusRequiresCompatibilityAndNonemptyDomainOverlap() {
		OracleBag left = OracleBag.empty().plus(binding("x", 1L), 2);

		assertEquals(left, left.minus(OracleBag.empty().plus(binding("y", 9L), 5)));
		assertEquals(OracleBag.empty(), left.minus(OracleBag.empty().plus(binding("x", 1L, "y", 9L), 1)));
		assertEquals(left, left.minus(OracleBag.empty().plus(OracleBinding.empty(), 5)));
	}

	@Test
	void optionalEmitsMatchedAndUnmatchedMasksWithBagMultiplicity() {
		OracleBag left = OracleBag.empty().plus(binding("x", 1L), 2).plus(binding("x", 2L), 3);
		OracleBag right = OracleBag.empty()
				.plus(binding("x", 1L, "y", 10L), 4)
				.plus(binding("x", 1L, "y", 11L), 1);

		OracleBag result = left.optional(right);

		assertEquals(BigInteger.valueOf(8L), result.multiplicity(binding("x", 1L, "y", 10L)));
		assertEquals(BigInteger.valueOf(2L), result.multiplicity(binding("x", 1L, "y", 11L)));
		assertEquals(BigInteger.valueOf(3L), result.multiplicity(binding("x", 2L)));
		assertEquals(BigInteger.valueOf(13L), result.cardinality());
		assertEquals(2, OracleFrontierMeasure.fromBag(result, XY).byMask().size());
	}

	@Test
	void exactTermIdsRatherThanHashesEstablishBindingEquality() {
		OracleBinding first = binding("x", 1L);
		OracleBinding same = binding("x", 1L);
		OracleBinding different = binding("x", 2L);

		assertEquals(first, same);
		assertNotEquals(first, different);
		assertTrue(first.compatibleWith(same));
		assertFalse(first.compatibleWith(different));
		assertThrows(IllegalArgumentException.class, () -> first.merge(different));
	}

	private static OracleBinding binding(Object... values) {
		if (values.length % 2 != 0) {
			throw new IllegalArgumentException("binding requires name/value pairs");
		}
		LinkedHashMap<String, Long> result = new LinkedHashMap<>();
		for (int index = 0; index < values.length; index += 2) {
			result.put((String) values[index], (Long) values[index + 1]);
		}
		return OracleBinding.of(result);
	}
}
